//! Everything a ban of the player's own can name, generated by `scripts/er-duel-rules-gen.py`
//! from the installed game, the same catalog the Frida agent and the Cheat Engine table carry.
//! Do not edit: rerun `python3 scripts/er-duel-rules-gen.py --write`.

use crate::bans::Entry;

/// One name and what it stands for, as a condition entry lists it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Row {
    pub name: &'static str,
    pub ids: &'static [i32],
    pub bullets: &'static [i32],
    pub effects: &'static [i32],
}

impl Row {
    /// The row as a condition entry.
    pub fn entry(&self) -> Entry {
        Entry {
            name: self.name.to_owned(),
            ids: self.ids.to_vec(),
            bullets: self.bullets.to_vec(),
            effects: self.effects.to_vec(),
        }
    }
}

const fn row(
    name: &'static str,
    ids: &'static [i32],
    bullets: &'static [i32],
    effects: &'static [i32],
) -> Row {
    Row {
        name,
        ids,
        bullets,
        effects,
    }
}

